public sealed class CountingStream : Stream {
    private readonly Stream _inner;
    private long _bytes;
    public CountingStream(Stream inner) { _inner = inner; }

    public override int Read(byte[] b, int off, int cnt) {
        int n = _inner.Read(b, off, cnt);        // delegate to the wrapped stream
        _bytes += n;
        return n;
    }
    public override long Length => _inner.Length; // every other member forwards too
}

